import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { Slot } from 'src/entities/slot.entity';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { EntityManager } from 'typeorm';
import { Resource } from 'src/entities/resource.entity';
import {
  CreateSlotDto,
  ResourceSlotsDto,
  SlotDto,
  UpdateSlotTimesDto,
} from './types/dtos/slots.dto';

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  async getSlots(): Promise<ResourceSlotsDto[]> {
    const [dependencies, resources, allSlots] = await Promise.all([
      this.manager.find(BlockingDependency),
      this.manager.find(Resource, { order: { id: 'ASC' } }),
      this.manager.find(Slot, { order: { start: 'ASC', id: 'ASC' } }),
    ]);

    const { todayStart, tomorrowStart } = this.getTodayBounds();
    const todaySlots = allSlots.filter(
      (slot) => slot.start < tomorrowStart && slot.end > todayStart,
    );

    const upstreamBlockersByResourceId =
      this.buildUpstreamBlockersMap(dependencies);
    const slotDtosByResourceId = this.buildSlotDtosByResourceId(todaySlots);

    const resourceIdsWithSlots = new Set(
      todaySlots.map((slot) => slot.resourceId),
    );
    for (const resourceId of resourceIdsWithSlots) {
      this.computeConflictsForResource(
        resourceId,
        slotDtosByResourceId,
        upstreamBlockersByResourceId,
      );
    }

    return resources.map((resource) => ({
      resourceId: resource.id,
      slots: this.buildDisplaySlots(
        resource.id,
        slotDtosByResourceId,
        upstreamBlockersByResourceId,
      ),
    }));
  }

  async addSlot(createSlot: CreateSlotDto): Promise<SlotDto> {
    // TODO: Implement this method.
    // Check for conflicts before saving. Reject with 409 if any exist.

    return this.manager.save(
      Slot.create({
        name: createSlot.name,
        start: createSlot.start,
        end: createSlot.end,
        resourceId: createSlot.resourceId,
      }),
    );
  }

  async updateSlot(
    slotId: number,
    updateSlot: UpdateSlotTimesDto,
  ): Promise<SlotDto> {
    // TODO: Implement this method.
    // Check for conflicts before saving. Reject with 409 if any exist.

    const slot = await this.manager.findOneOrFail(Slot, {
      where: { id: slotId },
    });

    slot.start = updateSlot.start;
    slot.end = updateSlot.end;
    await this.manager.save(slot);

    return {
      ...slot,
      conflicts: [],
    };
  }

  private getTodayBounds(): { todayStart: string; tomorrowStart: string } {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    return {
      todayStart: `${this.formatDate(today)}T00:00:00`,
      tomorrowStart: `${this.formatDate(tomorrow)}T00:00:00`,
    };
  }

  private formatDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  private buildUpstreamBlockersMap(
    dependencies: BlockingDependency[],
  ): Map<number, Set<number>> {
    const upstreamBlockersByResourceId = new Map<number, Set<number>>();

    for (const dependency of dependencies) {
      const blockers =
        upstreamBlockersByResourceId.get(dependency.blockedResourceId) ??
        new Set<number>();
      blockers.add(dependency.blockingResourceId);
      upstreamBlockersByResourceId.set(
        dependency.blockedResourceId,
        blockers,
      );
    }

    return upstreamBlockersByResourceId;
  }

  private buildSlotDtosByResourceId(
    slots: Slot[],
  ): Map<number, SlotDto[]> {
    const slotDtosByResourceId = new Map<number, SlotDto[]>();

    for (const slot of slots) {
      const slotDto: SlotDto = {
        id: slot.id,
        name: slot.name,
        start: slot.start,
        end: slot.end,
        resourceId: slot.resourceId,
        conflicts: [],
      };

      const resourceSlots = slotDtosByResourceId.get(slot.resourceId) ?? [];
      resourceSlots.push(slotDto);
      slotDtosByResourceId.set(slot.resourceId, resourceSlots);
    }

    return slotDtosByResourceId;
  }

  private getConflictResourceIds(
    resourceId: number,
    upstreamBlockersByResourceId: Map<number, Set<number>>,
  ): Set<number> {
    const conflictResourceIds = new Set<number>([resourceId]);
    const upstreamBlockers = upstreamBlockersByResourceId.get(resourceId);

    if (upstreamBlockers) {
      for (const blockerId of upstreamBlockers) {
        conflictResourceIds.add(blockerId);
      }
    }

    return conflictResourceIds;
  }

  private isConflictCandidate(
    slotResourceId: number,
    otherResourceId: number,
    upstreamBlockersByResourceId: Map<number, Set<number>>,
  ): boolean {
    if (slotResourceId === otherResourceId) {
      return true;
    }

    return (
      upstreamBlockersByResourceId.get(slotResourceId)?.has(otherResourceId) ??
      false
    );
  }

  /**
   * Finds overlapping slots among same-resource and upstream-blocker candidates,
   * using start-time ordering to prune comparisons.
   */
  private computeConflictsForResource(
    resourceId: number,
    slotDtosByResourceId: Map<number, SlotDto[]>,
    upstreamBlockersByResourceId: Map<number, Set<number>>,
  ): void {
    const conflictResourceIds = this.getConflictResourceIds(
      resourceId,
      upstreamBlockersByResourceId,
    );
    const candidates = [...conflictResourceIds]
      .flatMap((id) => slotDtosByResourceId.get(id) ?? [])
      .sort((left, right) =>
        left.start === right.start
          ? left.id - right.id
          : left.start.localeCompare(right.start),
      );

    for (let i = 0; i < candidates.length; i++) {
      const left = candidates[i];

      for (let j = i + 1; j < candidates.length; j++) {
        const right = candidates[j];

        if (right.start >= left.end) {
          break;
        }

        if (left.start >= right.end || left.end <= right.start) {
          continue;
        }

        if (
          this.isConflictCandidate(
            left.resourceId,
            right.resourceId,
            upstreamBlockersByResourceId,
          )
        ) {
          this.addConflict(left, right);
        }

        if (
          this.isConflictCandidate(
            right.resourceId,
            left.resourceId,
            upstreamBlockersByResourceId,
          )
        ) {
          this.addConflict(right, left);
        }
      }
    }
  }

  private addConflict(slot: SlotDto, conflict: SlotDto): void {
    const alreadyListed = slot.conflicts?.some(
      (existing) => existing.id === conflict.id,
    );

    if (alreadyListed) {
      return;
    }

    slot.conflicts?.push({
      id: conflict.id,
      name: conflict.name,
      start: conflict.start,
      end: conflict.end,
      resourceId: conflict.resourceId,
    });
  }

  private buildDisplaySlots(
    resourceId: number,
    slotDtosByResourceId: Map<number, SlotDto[]>,
    upstreamBlockersByResourceId: Map<number, Set<number>>,
  ): SlotDto[] {
    const displayResourceIds = this.getConflictResourceIds(
      resourceId,
      upstreamBlockersByResourceId,
    );
    const seenSlotIds = new Set<number>();
    const displaySlots: SlotDto[] = [];

    for (const displayResourceId of displayResourceIds) {
      for (const slot of slotDtosByResourceId.get(displayResourceId) ?? []) {
        if (seenSlotIds.has(slot.id)) {
          continue;
        }

        seenSlotIds.add(slot.id);
        displaySlots.push(slot);
      }
    }

    return displaySlots.sort((left, right) =>
      left.start === right.start
        ? left.id - right.id
        : left.start.localeCompare(right.start),
    );
  }
}

